using RuleHealth.Core.Extraction;
using RuleHealth.Core.Model;
using RuleHealth.Core.Storage;

namespace RuleHealth.Tests;

public class CheckIdentityTests
{
    [Theory]
    // Fixed vectors from samples/hybridbrothers/candidates.json (generated by the PowerShell spike).
    [InlineData("AADNonInteractiveUserSignInLogs", "AppDisplayName", null, "eq", "Copilot App", "4dd2a44af069835a")]
    [InlineData("AADNonInteractiveUserSignInLogs", "AppDisplayName", null, "eq", "Microsoft Azure CLI", "bafce7ef9e48b59f")]
    public void Known_vectors(string table, string column, string? path, string operatorClass, string value, string expected)
    {
        Assert.Equal(expected, CheckIdentity.Compute(table, column, path, operatorClass, value));
    }

    [Fact]
    public void Null_path_hashes_like_empty_path()
    {
        Assert.Equal(
            CheckIdentity.Compute("T", "C", null, "eq", "v"),
            CheckIdentity.Compute("T", "C", "", "eq", "v"));
    }

    [Fact]
    public void Hash_is_case_sensitive()
    {
        Assert.NotEqual(
            CheckIdentity.Compute("IdentityInfo", "AccountUPN", null, "eq", "x"),
            CheckIdentity.Compute("IdentityInfo", "AccountUpn", null, "eq", "x"));
    }

    [Fact]
    public void Every_sample_check_has_the_right_id()
    {
        var candidates = JsonStore.ReadFile<CandidatesDocument>(Path.Combine(TestPaths.Samples, "hybridbrothers", "candidates.json"));
        Assert.NotEmpty(candidates.Checks);

        var wrong = candidates.Checks.Where(c => CheckIdentity.Compute(c) != c.CheckId).Select(c => c.CheckId).ToList();

        Assert.Empty(wrong);
        Assert.Equal(candidates.Checks.Count, candidates.Checks.Select(c => c.CheckId).Distinct().Count());
    }
}
